def page(acc,body,cls="",bg=""):
  return f'<!doctype html><html lang="ja"><head><meta charset="utf-8"><style>{CSS}</style></head><body class="{cls}" style="--ac:{acc};{bg}">{body}</body></html>'
def bar(name,sub="",right=""):
  return f'<div class="bar"><span class="dot"></span><b>{name}</b><span class="sub">{sub}</span><div class="r">{right}</div></div>'
def lines(*w):return "".join(f'<div class="ln" style="width:{x}%;margin:9px 0"></div>' for x in w)
def spark(pts,col,w=300,h=90,fill=True):
  n=len(pts);mx=max(pts);mn=min(pts);xy=[(i*w/(n-1),h-4-(p-mn)/(mx-mn or 1)*(h-12)) for i,p in enumerate(pts)]
  d="M"+" L".join(f"{x:.1f},{y:.1f}" for x,y in xy)
  a=f'<path d="{d} L{w},{h} L0,{h} Z" fill="{col}" opacity=".12"/>' if fill else ""
  return f'<svg width="{w}" height="{h}" viewBox="0 0 {w} {h}">{a}<path d="{d}" fill="none" stroke="{col}" stroke-width="2.5" stroke-linejoin="round"/></svg>'

