T[138]=("週1のプロジェクト裁定カード（出す1本・しまう1本・断りの下書きの3枠。引き出しのモチーフ）",page("#8a6d3b",'<div class="app">'+bar("しまっちゃうよおじさん","毎週日曜 20:00 の裁定",'<span class="chip">今週 11/16–11/22</span>')+'''<div class="main">'''+"".join(f'<div class="card" style="flex:1;display:flex;flex-direction:column;{s}"><svg width="100%" height="120" viewBox="0 0 200 120"><rect x="30" y="10" width="140" height="100" rx="8" fill="#efe6d6" stroke="#8a6d3b" stroke-width="3"/><rect x="42" y="{y}" width="116" height="40" rx="5" fill="{f}" stroke="#8a6d3b" stroke-width="3"/><rect x="88" y="{y+16}" width="24" height="8" rx="4" fill="#8a6d3b"/></svg><span class="chip {k}" style="align-self:flex-start;margin-top:10px">{a}</span><div class="t" style="font-size:16px;margin-top:8px">{b}</div><div class="mut" style="margin-top:4px">{c}</div></div>' for a,b,c,k,y,f,s in [("出す1本","作品集サイトの公開","今週いちばん完成に近い","ok",22,"#fff","outline:2px solid #1d7a3e"),("しまっちゃう1本","古い計測ツール","3週間うごきなし","",60,"#d9cdb6",""),("断りの下書き","打ち合わせの辞退","やんわり断る文を用意","wa",40,"#fff","")])+'</div></div>'))

ITEMS=list(T)
def shoot(i):
  html=T[i][1];fd,p=tempfile.mkstemp(suffix=".html");os.write(fd,html.encode());os.close(fd)
  png=p+".png"
  subprocess.run([CH,"--headless=new","--hide-scrollbars","--disable-gpu","--force-device-scale-factor=2","--window-size=800,500","--virtual-time-budget=1500",f"--screenshot={png}","file://"+p],capture_output=True)
  Image.open(png).convert("RGB").resize((800,500),Image.LANCZOS).save(f"thumbs/app-{i}.jpg",quality=88)
  os.remove(p);os.remove(png);print("thumbs/app-%d.jpg"%i)
if __name__=="__main__":
  os.chdir(os.path.dirname(os.path.abspath(__file__)))
  args=[a for a in sys.argv[1:] if a!="--apply"]
  for i in [int(a) for a in args] or ITEMS:shoot(i)
  if "--apply" in sys.argv:  # thumb 空の該当作品にだけ入れる（既にあるものは触らない）。文字列置換で他の行・整形は変えない
    s=open("data.json").read();d=json.loads(s)
    for it in d["items"]:
      if it["id"] in T and not it.get("thumb"):
        it["thumb"]=f"thumbs/app-{it['id']}.jpg"
    open("data.json","w").write(json.dumps(d,ensure_ascii=False,indent=1))
